    <div v-else-if="tab==='console'" class="settings-form q-mt-md"><section class="settings-card"><h6>{{ t('neo.auto2.k5bd086d22a') }}</h6><q-toggle dark :model-value="bool('OverrideConsole')" :label="t('neo.auto2.k186772c65b')" @update:model-value="save('OverrideConsole',$event)"/><q-toggle dark :model-value="bool('ShowConsole')" :label="t('neo.auto2.kd6dca20f52')" :disable="!bool('OverrideConsole')" @update:model-value="save('ShowConsole',$event)"/><q-toggle dark :model-value="bool('AutoCloseConsole')" :label="t('neo.auto2.k7a434e1b3c')" :disable="!bool('OverrideConsole')" @update:model-value="save('AutoCloseConsole',$event)"/><q-toggle dark :model-value="bool('ShowConsoleOnError')" :label="t('neo.auto2.k1f4eac88bb')" :disable="!bool('OverrideConsole')" @update:model-value="save('ShowConsoleOnError',$event)"/><q-input dark outlined type="number" class="q-mt-sm" :model-value="number('ConsoleMaxLines')" :label="t('neo.auto2.k2c6d5f0755')" @update:model-value="save('ConsoleMaxLines',Number($event))"/><q-toggle dark :model-value="bool('ConsoleOverflowStop')" :label="t('neo.auto2.k196c0a7d88')" @update:model-value="save('ConsoleOverflowStop',$event)"/></section></div>
