'neo.auto2.kc23c1a48a6') }}</h6><q-toggle dark :model-value="bool('OverrideAssetVerification')" :label="t('neo.auto2.k3eade41878')" @update:model-value="save('OverrideAssetVerification',$event)"/><q-select dark outlined :model-value="number('AssetVerificationMode')" :options="[{label:t('neo.auto2.k43412d74a3'),value:0},{label:t('neo.auto2.kf9c6853b73'),value:1},{label:t('neo.auto2.k89aa46edff'),value:2},{label:t('neo.auto2.k53b916d50c'),value:3}]" emit-value map-options :label="t('neo.auto2.k12324b012b')" @update:model-value="save('AssetVerificationMode',$event)"/><q-input dark outlined type="number" :model-value="number('AssetCacheExpiryDays')" :label="t('neo.auto2.k559395a640')" @update:model-value="save('AssetCacheExpiryDays',Number($event))"/></section></div>
