<script setup lang="ts">
import { useI18n } from "vue-i18n";
const { t } = useI18n();
import { computed, ref } from 'vue';
import SettingsPanel from './SettingsPanel.vue';
const props=defineProps<{settings:any[];busy:boolean;scope:Record<string,unknown>;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>}>();
const tab=ref('runtime'),error=ref('');
const setting=(key:string)=>props.settings.find(x=>x.key===key); const value=(key:string)=>setting(key)?.value;
const bool=(key:string)=>Boolean(value(key)); const text=(key:string)=>String(value(key) ?? ''); const number=(key:string)=>Number(value(key) ?? 0);
const memoryWarning=computed(()=>number('MaxMemAlloc')>0 && number('MinMemAlloc')>number('MaxMemAlloc'));
async function save(key:string,newValue:any){error.value='';try{await props.execute('settings.set',{...props.scope,key,value:newValue});}catch(e){error.value=String(e);}}
async function reset(key:string){error.value='';try{await props.execute('settings.reset',{...props.scope,key});}catch(e){error.value=String(e);}}
async function diagnoseJava(){error.value='';try{const r=await props.execute('java.diagnose',{...props.scope,arguments:text('JvmArgs')});if(r?.recommendations?.length)error.value=r.recommendations.join('；');}catch(e){error.value=String(e);}}
</script>
<style scoped>
.instance-settings-panel{max-width:1120px}.settings-form{display:grid;gap:16px}.settings-card{padding:20px;border:1px solid var(--neo-border);border-radius:16px;background:var(--neo-panel)}.settings-card h6{margin:0 0 14px;font-size:18px}.settings-card .q-toggle{display:block;margin:7px 0}.settings-card .q-input,.settings-card .q-select{margin-top:10px}
</style>
